import{_ as d}from"./chunks/ubuntu22_logo.CkPFtFeF.js";import{c as a,Q as i,j as e,m as o}from"./chunks/framework.DjobWxAB.js";const p=JSON.parse('{"title":"개발자 가이드","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/developers-guide.md","filePath":"ko/software/developers-guide.md","lastUpdated":1779182288000}'),l={name:"ko/software/developers-guide.md"};function r(h,t,s,n,c,u){return i(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="개발자-가이드" tabindex="-1">개발자 가이드 <a class="header-anchor" href="#개발자-가이드" aria-label="Permalink to &quot;개발자 가이드&quot;">​</a></h1><h2 id="📚-소개" tabindex="-1">📚 소개 <a class="header-anchor" href="#📚-소개" aria-label="Permalink to &quot;📚 소개&quot;">​</a></h2><p><strong>RBQ 시뮬레이션, 명령 및 배포/업데이트 매뉴얼에 오신 것을 환영합니다</strong></p><p>이 매뉴얼은 RBQ 로봇을 <strong>시뮬레이션</strong>하고 명령하며 실제 로봇에 자신만의 알고리즘을 <strong>배포</strong>하는 방법에 대한 종합적인 가이드를 제공합니다.</p><h2 id="✅-🖥️-개발자를-위한-시뮬레이터-및-gui" tabindex="-1">✅ 🖥️ 개발자를 위한 시뮬레이터 및 GUI <a class="header-anchor" href="#✅-🖥️-개발자를-위한-시뮬레이터-및-gui" aria-label="Permalink to &quot;✅ 🖥️ 개발자를 위한 시뮬레이터 및 GUI&quot;">​</a></h2><ul><li>RBQ 로봇은 <strong>MuJoCo</strong>를 사용하여 정확하게 시뮬레이션할 수 있습니다. 📝 <em>개발자는 다음 파일을 편집하여 시뮬레이션 환경 &quot;playground&quot;를 수정할 수 있습니다:</em> <code>resources/model/environment.xml</code></li><li><strong>RBQ GUI</strong>는 사용자가 로봇에 명령을 내리고 모니터링할 수 있는 직관적인 인터페이스를 제공하도록 설계되었습니다. <ul><li>로봇 상태, 센서 상태에 대한 시각적 피드백을 제공하며 키보드와 조이스틱 입력을 모두 지원합니다.</li></ul></li></ul><h2 id="gui-개요" tabindex="-1">GUI 개요 <a class="header-anchor" href="#gui-개요" aria-label="Permalink to &quot;GUI 개요&quot;">​</a></h2><ul><li>이 섹션에서는 <strong>RBQ GUI</strong> 사용 방법을 설명하며, 주요 기능과 인터페이스 레이아웃을 포함합니다.</li></ul><p>GUI Connect</p><ul><li>[1] : 상단 패널</li><li>[2] : 중앙 패널</li><li>[3] : 3D 패널</li></ul><h3 id="📌-상단-패널" tabindex="-1">📌 상단 패널 <a class="header-anchor" href="#📌-상단-패널" aria-label="Permalink to &quot;📌 상단 패널&quot;">​</a></h3><p>상단 패널은 로봇 연결, 초기 자세, 모터 상태 확인 등 핵심 기능을 제공합니다. 비상 정지 버튼과 배터리 전압 및 IMU 센서 상태 표시기도 포함되어 있습니다.</p><ul><li><strong>Connection Status and Buttons:</strong> 로봇 연결 여부를 표시합니다. 이 버튼을 사용하여 로봇과 연결하거나 끊을 수 있습니다.</li><li><strong>Auto Start</strong> 버튼: [Motor Check --&gt; Initialize Pose --&gt; Control Start] 순서로 로봇을 자동으로 초기화하고 제어 시스템을 준비합니다.</li><li><strong>Motor Check / Initialize Pose / Control Start</strong> 버튼: 각각의 시작 동작을 개별적으로 수행할 수 있습니다. 하지만 <strong>Auto Start</strong> 버튼을 사용하는 것이 권장됩니다.<br> 📝 <em>시뮬레이션: Control Start 버튼만 초록색으로 표시됩니다. 실제 로봇: 준비되면 세 버튼 표시등이 모두 초록색으로 변경됩니다.</em></li><li><strong>EMERGENCY</strong> 버튼: 로봇의 모든 동작을 즉시 중단하여 로봇이 부드럽게 내려앉도록 합니다. <ul><li>비상 정지 후 동작을 재개하려면 <strong>Gait select</strong> 그룹 박스에서 <strong>Stance</strong> 버튼을 누르십시오. 📝 <em>시스템은 stance motion(초록색)으로 전환하기 전에 RECOVERY 모드(노란색)로 진입합니다.</em></li></ul></li></ul><h3 id="📌-중앙-패널" tabindex="-1">📌 중앙 패널 <a class="header-anchor" href="#📌-중앙-패널" aria-label="Permalink to &quot;📌 중앙 패널&quot;">​</a></h3><ul><li><p>중앙 패널에는 로봇에 다양한 명령을 보내기 위한 버튼이 있는 탭이 포함되어 있습니다. 📝 <em>실제 로봇에서는 추가적으로 <strong>관절, 펌웨어, 전원</strong> 탭이 있지만 사용하지 않는 것을 권장합니다.</em></p></li><li><p><strong>[ 보행 탭 ]</strong> 로봇의 걷기 동작과 보행 방식 간 전환을 명령합니다.</p><table tabindex="0"><thead><tr><th>✅ 버튼 동작</th><th>Sit</th><th>Stance</th><th>Walk</th><th>Stairs</th><th>Running</th><th>RL-trot</th><th>RL-pronk</th></tr></thead></table><p>⌨️ 키보드 키 1 2 3 4 5 R F</p></li></ul><h3 id="📌-3d-패널" tabindex="-1">📌 3D 패널 <a class="header-anchor" href="#📌-3d-패널" aria-label="Permalink to &quot;📌 3D 패널&quot;">​</a></h3><ul><li>이 패널은 연결된 로봇의 현재 자세를 3D로 렌더링한 디지털 트윈을 표시합니다.</li></ul><h2 id="📦-설치" tabindex="-1">📦 설치 <a class="header-anchor" href="#📦-설치" aria-label="Permalink to &quot;📦 설치&quot;">​</a></h2><ul><li>이 섹션에서는 처음부터 RBQ 로봇 시뮬레이션 및 개발 환경을 설치하고 설정하는 방법을 설명합니다.</li></ul><h3 id="💻-시스템-요구사항" tabindex="-1">💻 시스템 요구사항 <a class="header-anchor" href="#💻-시스템-요구사항" aria-label="Permalink to &quot;💻 시스템 요구사항&quot;">​</a></h3><p>RBQ 시뮬레이션 및 배포 환경을 원활하게 실행하기 위해 다음 요구사항이 권장됩니다:</p><ul><li>운영 체제: Ubuntu 22.04 (x86) <img src="'+d+'" alt="GUI Connect"></li><li>최소 PC 사양: <ul><li>CPU: Intel Core i7 12세대</li><li>RAM: 16 GB</li><li>저장 공간: 25 GB</li></ul></li><li>제어 장치 <ul><li>키보드: W, A, S, D, Q, E, R, F, [1-5] 키</li><li>조이스틱: Logitech Wireless Gamepad F710 (권장) GUI Connect</li></ul></li></ul><h3 id="📥-1-rbq-저장소-다운로드" tabindex="-1">📥 1. RBQ 저장소 다운로드 <a class="header-anchor" href="#📥-1-rbq-저장소-다운로드" aria-label="Permalink to &quot;📥 1. RBQ 저장소 다운로드&quot;">​</a></h3><ul><li>다음 명령어를 사용하여 저장소를 복제하세요:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span></code></pre></div><h3 id="🛠️-2-환경-설정" tabindex="-1">🛠️ 2. 환경 설정 <a class="header-anchor" href="#🛠️-2-환경-설정" aria-label="Permalink to &quot;🛠️ 2. 환경 설정&quot;">​</a></h3><ul><li>다음 명령어를 사용하여 필요한 라이브러리를 설치하세요:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/ex/install/setup.bash</span></span></code></pre></div><h2 id="▶️-시뮬레이션" tabindex="-1">▶️ 시뮬레이션 <a class="header-anchor" href="#▶️-시뮬레이션" aria-label="Permalink to &quot;▶️ 시뮬레이션&quot;">​</a></h2><ul><li>스크립트를 사용하여 <strong>RBQ 제어 모듈, MuJoCo 시뮬레이터 및 GUI</strong>를 함께 시작합니다.</li></ul><p><strong>참고:</strong> <em><code>인자:</code></em></p><ul><li><code>--help</code> : 도움말 메시지를 표시하고 종료합니다.</li><li><code>--vision</code> : 비전 모듈을 실행합니다 (예: 비전 센서, 계단 오르기 활성화).</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span></span></code></pre></div><ul><li>프롬프트가 표시되면 새로 열린 CLI 터미널에서 <code>사용자 비밀번호</code>를 입력하여 프로세스를 시작합니다.</li></ul><h3 id="🔗-초기화-시뮬레이션-로봇-연결-및-시작" tabindex="-1">🔗 초기화 - 시뮬레이션 로봇 연결 및 시작 <a class="header-anchor" href="#🔗-초기화-시뮬레이션-로봇-연결-및-시작" aria-label="Permalink to &quot;🔗 초기화 - 시뮬레이션 로봇 연결 및 시작&quot;">​</a></h3><ul><li><code>RBQ GUI</code>에서 <strong>Connect</strong> 버튼을 클릭하여 연결을 설정합니다. <ul><li>성공하면 <code>연결 표시등</code>이 <strong>Simulator Connected</strong> 텍스트와 <strong>파란색</strong>으로 변경됩니다.</li></ul></li><li><code>RBQ GUI</code>에서 <strong>Auto Start</strong> 버튼을 클릭하여 제어를 시작합니다. <ul><li>성공하면 <code>연결 표시등</code>이 <strong>초록색</strong>으로 변경됩니다.</li></ul></li></ul><h3 id="📌-stance-로봇이-서도록-명령하기" tabindex="-1">📌 Stance - 로봇이 서도록 명령하기 <a class="header-anchor" href="#📌-stance-로봇이-서도록-명령하기" aria-label="Permalink to &quot;📌 Stance - 로봇이 서도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; tab --&gt; &quot;Gait select&quot; group-box --&gt; &quot;Stance&quot; 버튼</code> 또는 키보드 버튼 <code>2</code>를 누르세요</li><li>명령이 내려지면 로봇이 서 있는 자세로 이동하기 시작합니다. 완료되면 추가 명령에 응답합니다. <ul><li>📝 <em>현재 자세에 따라 서 있는 자세로 전환하는 데 몇 초가 걸릴 수 있습니다.</em></li></ul></li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Nose up / down</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Roll Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td>Height up / down</td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full range of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결되면 키보드의 숫자 키만 바인딩됩니다.</em></li></ul><hr><h3 id="📌-walk-로봇이-걷도록-명령하기" tabindex="-1">📌 Walk - 로봇이 걷도록 명령하기 <a class="header-anchor" href="#📌-walk-로봇이-걷도록-명령하기" aria-label="Permalink to &quot;📌 Walk - 로봇이 걷도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Walk&quot; 버튼</code> 또는 키보드 버튼 <code>3</code>을 누르세요</li><li>명령이 내려지면 로봇이 걷기 보행으로 전환됩니다. 완료되면 추가 명령에 응답합니다.</li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Go Forward / Backward</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Go Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td>Pitch Forward / Backward</td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결되면 키보드의 숫자 키만 바인딩됩니다.</em></li></ul><hr><h3 id="📌-stair-로봇이-계단을-오르도록-명령하기" tabindex="-1">📌 Stair - 로봇이 계단을 오르도록 명령하기 <a class="header-anchor" href="#📌-stair-로봇이-계단을-오르도록-명령하기" aria-label="Permalink to &quot;📌 Stair - 로봇이 계단을 오르도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Stairs&quot; 버튼</code> 또는 키보드 버튼 <code>4</code>를 누르세요</li><li>로봇은 비전 기능을 활용하여 계단을 올라갑니다.</li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Go Forward / Backward</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Go Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td></td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결되면 키보드의 숫자 키만 바인딩됩니다.</em></li></ul><hr><h3 id="📌-run-로봇이-달리도록-명령하기" tabindex="-1">📌 Run - 로봇이 달리도록 명령하기 <a class="header-anchor" href="#📌-run-로봇이-달리도록-명령하기" aria-label="Permalink to &quot;📌 Run - 로봇이 달리도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Running&quot; 버튼</code> 또는 키보드 버튼 <code>5</code>를 누르세요</li><li>로봇은 빠르고 민첩한 동작을 수행합니다. <ul><li>📝 <em>달리기로 전환하기 전에 현재 자세와 보행에 따라 STANCE 자세로 전환해야 할 수 있습니다.</em></li></ul></li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Go Forward / Backward</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Go Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td></td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결되면 키보드의 숫자 키만 바인딩됩니다.</em></li></ul><hr><h3 id="📌-wave-로봇이-부드럽게-걷도록-명령하기" tabindex="-1">📌 Wave - 로봇이 부드럽게 걷도록 명령하기 <a class="header-anchor" href="#📌-wave-로봇이-부드럽게-걷도록-명령하기" aria-label="Permalink to &quot;📌 Wave - 로봇이 부드럽게 걷도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Wave&quot; 버튼</code></li><li>로봇은 Wave 보행 패턴으로 부드럽게 걷습니다.</li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Go Forward / Backward</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Go Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td>Pitch Forward / Backward</td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결되면 키보드의 숫자 키만 바인딩됩니다.</em></li></ul><hr><h3 id="📌-aim-로봇을-목표물에-향하도록-명령하기" tabindex="-1">📌 Aim - 로봇을 목표물에 향하도록 명령하기 <a class="header-anchor" href="#📌-aim-로봇을-목표물에-향하도록-명령하기" aria-label="Permalink to &quot;📌  Aim - 로봇을 목표물에 향하도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Aiming&quot; 버튼</code></li><li>이 모드를 사용하여 로봇을 특정 목표물이나 방향으로 정확하게 조준합니다.</li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Nose up / down</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td></td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td></td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><p>-📝 <em>조이스틱이 연결되면 키보드의 숫자 키만 바인딩됩니다.</em></p><hr><h3 id="📌-rl-trot-로봇이-rl-trot-하도록-명령하기" tabindex="-1">📌 RL-Trot - 로봇이 RL-Trot 하도록 명령하기 <a class="header-anchor" href="#📌-rl-trot-로봇이-rl-trot-하도록-명령하기" aria-label="Permalink to &quot;📌 RL-Trot - 로봇이 RL-Trot 하도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;RL-Trot&quot; 버튼</code> 또는 키보드 버튼 <code>R</code>를 누르세요</li><li>이 모드는 강화 학습 정책으로 생성된 Trot 보행을 활성화합니다. 로봇은 RL 기반 걷기 보행으로 전환되고 이후 사용자 명령에 응답합니다.</li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Go Forward / Backward</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Go Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td>Pitch Forward / Backward</td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결되면 키보드의 숫자 키만 바인딩됩니다.</em></li></ul><hr><h3 id="📌-rl-pronk-로봇이-rl-pronk-하도록-명령하기" tabindex="-1">📌 RL-Pronk - 로봇이 RL-Pronk 하도록 명령하기 <a class="header-anchor" href="#📌-rl-pronk-로봇이-rl-pronk-하도록-명령하기" aria-label="Permalink to &quot;📌 RL-Pronk - 로봇이 RL-Pronk 하도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;RL-Pronk&quot; 버튼</code> 또는 키보드 버튼 <code>F</code>를 누르세요</li><li>이 모드는 강화 학습 정책으로 생성된 Pronk 보행을 활성화합니다. 로봇은 RL 기반 Pronk 보행으로 전환되고 이후 사용자 명령에 응답합니다.</li></ul><table tabindex="0"><thead><tr><th>🕹️ Joystick</th><th>Command</th><th>Keyboard key</th><th>Robot Action</th></tr></thead><tbody><tr><td>L Stick</td><td>Forward / Backward</td><td>W / S</td><td>Go Forward / Backward</td></tr><tr><td>L Stick</td><td>Left / Right</td><td>Q / E</td><td>Go Left / Right</td></tr><tr><td>R Stick</td><td>Forward / Backward</td><td></td><td>Pitch Forward / Backward</td></tr><tr><td>R Stick</td><td>Left / Right</td><td>A / D</td><td>Turn Left / Right</td></tr><tr><td></td><td></td><td>Shift</td><td>Full speed of motion</td></tr></tbody></table><ul><li>📝 <em>조이스틱이 연결되면 키보드의 숫자 키만 바인딩됩니다.</em></li></ul><hr><h3 id="📌-sit-로봇을-앉히도록-명령하기" tabindex="-1">📌 Sit - 로봇을 앉히도록 명령하기 <a class="header-anchor" href="#📌-sit-로봇을-앉히도록-명령하기" aria-label="Permalink to &quot;📌 Sit - 로봇을 앉히도록 명령하기&quot;">​</a></h3><ul><li>경로: <code>&quot;Walk&quot; 탭 --&gt; &quot;Gait select&quot; 그룹 박스 --&gt; &quot;Sit&quot; 버튼</code> 또는 키보드 버튼 <code>1</code>를 누르세요</li><li>로봇이 부드럽게 앉은 자세로 전환하도록 명령합니다. <ul><li>📝 <em>현재 자세에 따라 앉은 자세로 전환하는 데 몇 초가 걸릴 수 있습니다.</em></li></ul></li></ul><h2 id="🤖-실제-로봇" tabindex="-1">🤖 실제 로봇 <a class="header-anchor" href="#🤖-실제-로봇" aria-label="Permalink to &quot;🤖 실제 로봇&quot;">​</a></h2><p>이 섹션에서는 <strong>실제 RBQ 로봇</strong>을 작동하는 방법을 설명합니다.</p><p>📖 <em>자세한 작동 단계는 <a href="https://rainbowrobotics.github.io/RBQ/ko/manual/Guides/common-guide.html" target="_blank" rel="noreferrer">작동 가이드</a>를 참조하세요</em></p><h3 id="_1-로봇에-연결하기" tabindex="-1">1. 로봇에 연결하기 <a class="header-anchor" href="#_1-로봇에-연결하기" aria-label="Permalink to &quot;1. 로봇에 연결하기&quot;">​</a></h3><ul><li>PC를 로봇의 Wi-Fi에 연결합니다. 📝 <em>Wi-Fi SSID: <code>RBQ_xxxx</code>.</em></li></ul><h3 id="_2-gui-실행-및-로봇-제어-설정" tabindex="-1">2. GUI 실행 및 로봇 제어 설정 <a class="header-anchor" href="#_2-gui-실행-및-로봇-제어-설정" aria-label="Permalink to &quot;2. GUI 실행 및 로봇 제어 설정&quot;">​</a></h3><p><code>bin</code> 디렉토리에서 <code>GUI</code>를 시작합니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/RBQ</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/GUI</span></span></code></pre></div><ul><li><strong>Connect</strong> 버튼을 클릭합니다. <ul><li>성공하면 <code>연결 표시등</code>이 <strong>Robot Connected</strong> 텍스트와 <strong>초록색</strong>으로 변경됩니다.</li></ul></li><li><strong>자동 시작</strong> 버튼을 클릭합니다. <ul><li>성공하면 <code>제어 표시등</code>이 <strong>초록색</strong>으로 변경되어 로봇이 성공적으로 활성화되었고 이제 작동 준비가 되었음을 나타냅니다.</li></ul></li></ul><h3 id="_3-명령은-시뮬레이션과-정확히-동일합니다" tabindex="-1">3. 명령은 시뮬레이션과 정확히 동일합니다 <a class="header-anchor" href="#_3-명령은-시뮬레이션과-정확히-동일합니다" aria-label="Permalink to &quot;3. 명령은 시뮬레이션과 정확히 동일합니다&quot;">​</a></h3><ul><li>📝 <em>먼저 시뮬레이터에서 로봇을 조종 하는 연습을 하는 것을 강력히 권장합니다.</em></li></ul><h2 id="🚀-로봇에-어플리케이션-바이너리-파일-배포하기" tabindex="-1">🚀 로봇에 어플리케이션(바이너리 파일) 배포하기 <a class="header-anchor" href="#🚀-로봇에-어플리케이션-바이너리-파일-배포하기" aria-label="Permalink to &quot;🚀 로봇에 어플리케이션(바이너리 파일) 배포하기&quot;">​</a></h2><ul><li>개발 PC에서 다음 명령어를 실행하여 로봇에 바이너리를 배포합니다:</li></ul><p><strong>참고:</strong> <em><code>인자:</code></em></p><ul><li><code>--help</code> : 도움말 메시지를 표시하고 종료합니다.</li><li><code>--scripts</code> : 새 스크립트 배포</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/deploy.bash</span></span></code></pre></div><p>SSH 비밀번호를 입력하라는 메시지가 표시됩니다.</p><ul><li><strong>비밀번호:</strong> 담당자에게 SSH 비밀번호를 문의하세요.</li><li>⚠️ 중요: <code>deploy.bash</code>가 완료되면 로봇을 껐다 켜서 새로 배포된 바이너리로 실행합니다.</li></ul>',97)])])}const b=a(l,[["render",r]]);export{p as __pageData,b as default};
